def longest_common_prefix(words):
    if not words:
        return 0
    max_length = 0
    for i in range(len(words[0])):
        common_char = words[0][i]
        max_length = max(max_length, i)
        for word in words[1:]:
            if word[i] != common_char:
                return max_length
    return max_length
