def can_form_word(tiles: str, word: str) -> bool:
    """ Check if a given word can be formed using the given tiles.
    """
    # Check if the length of the word is equal to the length of the tiles
    if len(word) != len(tiles):
        return False

    # Create a set of the tiles
    tile_set = set(tiles)

    # Check if the word is a permutation of the tiles
    return sorted(word) == sorted(tile_set)

