def shortest_substring(s):
    unique_chars = set(s)
    min_length = len(unique_chars)
    result = ""

    for i in range(len(s)):
        current_chars = set()
        for j in range(i, len(s)):
            current_chars.add(s[j])
            if len(current_chars) == min_length:
                result = s[i:j+1]
                break
        else:
            continue
        break

    return result

