def floyd_warshall(adjacency_matrix):
    n = len(adjacency_matrix)
    # Initialize the shortest paths matrix with infinity
    shortest_paths = [[float('inf')] * n for _ in range(n)]
    # Fill the matrix with the given adjacency matrix
    for i in range(n):
        for j in range(n):
            shortest_paths[i][j] = adjacency_matrix[i][j]
    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if shortest_paths[i][k] + shortest_paths[k][j] < shortest_paths[i][j]:
                    shortest_paths[i][j] = shortest_paths[i][k] + shortest_paths[k][j]
    return shortest_paths

