def wordLadderLength(beginWord, endWord, wordList):
    from collections import deque
    if not wordList or not beginWord or not endWord:
        return 0
    queue = deque()
    visited = set()
    queue.append((beginWord, 0))
    visited.add(beginWord)
    while queue:
        current, length = queue.popleft()
        if current == endWord:
            return length
        for word in wordList:
            if word == current:
                continue
            if word in visited:
                continue
            if len(word) != len(current):
                continue
            if word == endWord:
                return length + 1
            visited.add(word)
            queue.append((word, length + 1))

